#include <iostream>
#include <memory>
#include <string_view>
#include <vector>

class Notice {
public:
    virtual ~Notice() = default;
    virtual std::string_view text() const = 0;
};
class Welcome final : public Notice {
public:
    std::string_view text() const override { return "Welcome"; }
};
class Reminder final : public Notice {
public:
    std::string_view text() const override { return "Return soon"; }
    int days() const { return 3; }
};

int main()
{
    std::vector<std::unique_ptr<Notice>> notices;
    notices.push_back(std::make_unique<Welcome>());
    notices.push_back(std::make_unique<Reminder>());
    for (const auto& notice : notices) {
        std::cout << notice->text() << '\n';
        if (const auto* reminder = dynamic_cast<const Reminder*>(notice.get()))
            std::cout << "Days: " << reminder->days() << '\n';
    }
}
